147	    /**
148	     * The known E.164 country calling codes this owner's telephone may carry, used only to split the
149	     * stored number into its country code and national digits for display. Australia ('+61') and the
150	     * North American Numbering Plan ('+1') mirror the codes the create endpoint recognises.
151	     */
152	    private static final String[] KNOWN_COUNTRY_CODES = {"61", "1"};
153	
154	    /**
155	     * The stored E.164 {@code telephone} formatted for human reading: the country calling code (kept
156	     * with its leading {@code '+'}), a space, then the national digits grouped in threes from the left
157	     * and separated by spaces (e.g. {@code +61412345678} becomes {@code "+61 412 345 678"}). The
158	     * country code is taken as the longest {@link #KNOWN_COUNTRY_CODES} match, defaulting to a
159	     * two-digit code when none is recognised. It is a derived value; the raw {@code telephone} stays in
160	     * E.164 form.
161	     *
162	     * @return the human-formatted telephone, or the raw {@code telephone} when it is {@code null} or
163	     *         not in E.164 form
164	     */
165	    public String getTelephoneDisplay() {
166	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
167	            return this.telephone;
168	        }
169	        String digits = this.telephone.substring(1);
170	        String countryCode = null;
171	        for (String code : KNOWN_COUNTRY_CODES) {
172	            if (digits.startsWith(code) && digits.length() > code.length()
173	                && (countryCode == null || code.length() > countryCode.length())) {
174	                countryCode = code;
175	            }
176	        }
177	        if (countryCode == null) {
178	            countryCode = digits.substring(0, Math.min(2, digits.length()));
179	        }
180	        String national = digits.substring(countryCode.length());
181	        StringBuilder sb = new StringBuilder("+").append(countryCode);
182	        for (int i = 0; i < national.length(); i += 3) {
183	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
184	        }
185	        return sb.toString();
186	    }
