322	    /**
323	     * The fiscal year in which a date falls, where the fiscal year starts on 1 July. A date on or after
324	     * 1 July belongs to the fiscal year ending in the following calendar year; a date before 1 July
325	     * belongs to the fiscal year ending in that same calendar year. The returned value is the fiscal
326	     * year's ending calendar year (e.g. {@code 2026-08-10} yields {@code 2027}, {@code 2026-05-10}
327	     * yields {@code 2026}).
328	     *
329	     * @param date the date to classify
330	     * @return the ending calendar year of the fiscal year the date falls in
331	     */
332	    public static int fiscalYear(LocalDate date) {
333	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
334	    }
335	
336	    /**
337	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal
338	     * year (which starts on 1 July) that the business-day-adjusted {@code registrationDate} falls in
339	     * (e.g. a registration date of {@code 2026-08-10} yields {@code 'FY27'}). It is a derived,
340	     * non-persistent value; when no {@code registrationDate} is present it is {@code null}.
341	     *
342	     * @return the {@code 'FY<YY>'} fiscal year, or {@code null} when no registration date is present
343	     */
344	    public String getFiscalYear() {
345	        if (this.registrationDate == null) {
346	            return null;
347	        }
348	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
349	    }
350	
351	    /**
352	     * The owner's membership points, a non-negative score. It starts at 0 and accumulates: 2 points
353	     * when an email address is present, 1 point when the owner has no namesakes ({@code namesakeCount}
354	     * is zero), 2 points for a household of 3 or more members ({@code householdMemberCount} is at least
355	     * 3), and 3 points for tenure &mdash; the number of elapsed fiscal years (the fiscal year starts on
356	     * 1 July) from {@code registrationDate} to today &mdash; of more than 1.
357	     *
358	     * @return the derived membership points (0 or more)
359	     */
360	    public Integer getMembershipPoints() {
361	        int points = 0;
362	        if (this.email != null && !this.email.isBlank()) {
363	            points += 2;
364	        }
365	        if (this.namesakeCount != null && this.namesakeCount == 0) {
366	            points += 1;
367	        }
368	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
369	            points += 2;
370	        }
371	        if (this.registrationDate != null
372	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) > 1) {
373	            points += 3;
374	        }
375	        return points;
376	    }
377	
378	    /**
379	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
380	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
381	     * points.
382	     *
383	     * @return the derived membership level (1 to 4)
384	     */
385	    public Integer getMembershipLevel() {
386	        int points = getMembershipPoints();
387	        if (points >= 6) {
388	            return 4;
389	        }
390	        if (points >= 4) {
391	            return 3;
392	        }
393	        if (points >= 2) {
394	            return 2;
395	        }
396	        return 1;
397	    }
398	
399	    /**
400	     * The Luhn check digit (0-9) computed over the digits contained in this owner's
401	     * {@code customerCode}. Non-digit characters are ignored; the rightmost digit is doubled.
402	     *
403	     * @return the single Luhn check digit, or {@code null} when there is no customer code
404	     */
405	    public Integer getCheckDigit() {
406	        if (this.customerCode == null) {
407	            return null;
408	        }
409	        int sum = 0;
410	        boolean dbl = true;
411	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
412	            char c = this.customerCode.charAt(i);
413	            if (c < '0' || c > '9') {
414	                continue;
415	            }
416	            int d = c - '0';
417	            if (dbl) {
418	                d *= 2;
419	                if (d > 9) {
420	                    d -= 9;
421	                }
422	            }
423	            sum += d;
424	            dbl = !dbl;
425	        }
426	        return (10 - (sum % 10)) % 10;
427	    }
428	
429	    /**
430	     * The owner's age band, derived from {@code birthDate} computed against {@code registrationDate}:
431	     * {@code MINOR} when the owner is under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65
432	     * or older. It is a derived, non-persistent value; when no {@code birthDate} is present it is
433	     * {@code null}.
434	     *
435	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
436	     *         is present
437	     */
438	    public String getAgeBand() {
439	        if (this.birthDate == null) {
440	            return null;
441	        }
442	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
443	        int age = java.time.Period.between(this.birthDate, reference).getYears();
444	        if (age < 18) {
445	            return "MINOR";
446	        }
447	        if (age < 65) {
448	            return "ADULT";
449	        }
450	        return "SENIOR";
451	    }
452	
453	    /**
454	     * The owner's preferred contact channel, derived from the stored fields: {@code EMAIL} when an
455	     * email address is present, otherwise {@code PHONE}.
456	     *
457	     * @return {@code "EMAIL"} when an email address is present, otherwise {@code "PHONE"}
458	     */
459	    public String getContactPreference() {
460	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
461	    }
462	
463	    /**
464	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
465	     * owner's normalized telephone, its email (empty when none) and its {@code householdId} (empty
466	     * when none) joined by {@code '|'}. Because the telephone is part of the key, two members of the
467	     * same household with different telephones have different identity keys; only owners whose whole
468	     * key is identical are duplicates.
469	     *
470	     * @return the {@code normalizedTelephone|email|householdId} identity key
471	     */
472	    public String getIdentityKey() {
473	        String telephonePart = this.telephone == null ? "" : this.telephone;
474	        String emailPart = this.email == null ? "" : this.email;
475	        String householdPart = this.householdId == null ? "" : this.householdId;
476	        return telephonePart + '|' + emailPart + '|' + householdPart;
477	    }
478	
479	    protected Set<Pet> getPetsInternal() {
480	        if (this.pets == null) {
481	            this.pets = new HashSet<>();
482	        }
483	        return this.pets;
484	    }
485	
486	    protected void setPetsInternal(Set<Pet> pets) {
487	        this.pets = pets;
488	    }
489	
490	    public List<Pet> getPets() {
491	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
492	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
493	        return Collections.unmodifiableList(sortedPets);
494	    }
495	
496	    public void setPets(List<Pet> pets) {
497	        this.pets = new HashSet<>(pets);
498	    }
499	
500	    public void addPet(Pet pet) {
501	        getPetsInternal().add(pet);
502	        pet.setOwner(this);
503	    }
504	
505	    /**
506	     * Return the Pet with the given name, or null if none found for this Owner.
507	     *
508	     * @param name to test
509	     * @return true if pet name is already in use
510	     */
511	    public Pet getPet(String name) {
512	        return getPet(name, false);
513	    }
514	
515	    /**
516	     * Return the Pet with the given name, or null if none found for this Owner.
517	     *
518	     * @param name to test
519	     * @return true if pet name is already in use
520	     */
521	    public Pet getPet(String name, boolean ignoreNew) {
522	        name = name.toLowerCase();
523	        for (Pet pet : getPetsInternal()) {
524	            if (!ignoreNew || !pet.isNew()) {
525	                String compName = pet.getName();
526	                compName = compName.toLowerCase();
527	                if (compName.equals(name)) {
528	                    return pet;
529	                }
530	            }
531	        }
532	        return null;
533	    }
534	
535	    public Pet getPet(Integer petId) {
536	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
537	    }
538	
539	    @Override
540	    public String toString() {
541	        return new ToStringCreator(this)
542	
543	            .append("id", this.getId())
544	            .append("new", this.isNew())
545	            .append("lastName", this.getLastName())
546	            .append("firstName", this.getFirstName())
547	            .append("address", this.address)
548	            .append("city", this.city)
549	            .append("telephone", this.telephone)
550	            .toString();
551	    }
552	}
